import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

// Simple GEMM kernel: C (M x N) = A (M x K) * B (K x N)
// Optimized for the "tall-skinny x short-wide" case (small K, large M/N):
//  - threadIdx.x maps to output columns so B reads and C writes are coalesced
//  - threads in a warp share the same row of A, so A reads are broadcasts
//  - special fully-unrolled path when K == 32 keeps the A row in registers
__global__ void matmul_kernel(const float* __restrict__ A,
                              const float* __restrict__ B,
                              float* __restrict__ C,
                              int M, int K, int N) {
    int col = blockIdx.y * blockDim.x + threadIdx.x;  // output column (fast dim)
    int row = blockIdx.x * blockDim.y + threadIdx.y;  // output row
    if (row >= M || col >= N) return;

    const float* a_row = A + (long)row * K;
    float sum = 0.0f;
    if (K == 32) {
        #pragma unroll
        for (int k = 0; k < 32; ++k) {
            sum += a_row[k] * B[(long)k * N + col];
        }
    } else {
        for (int k = 0; k < K; ++k) {
            sum += a_row[k] * B[(long)k * N + col];
        }
    }
    C[(long)row * N + col] = sum;
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda() && B.is_cuda(), "Inputs must be CUDA tensors");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "Inputs must be 2D matrices");
    TORCH_CHECK(A.scalar_type() == torch::kFloat32 &&
                B.scalar_type() == torch::kFloat32,
                "Inputs must be float32");

    auto A_c = A.contiguous();
    auto B_c = B.contiguous();

    const int M = (int)A_c.size(0);
    const int K = (int)A_c.size(1);
    const int N = (int)B_c.size(1);
    TORCH_CHECK(B_c.size(0) == K, "Inner dimensions must match");

    auto C = torch::empty({M, N}, A_c.options());
    if (M == 0 || N == 0) return C;
    if (K == 0) return C.zero_();

    dim3 block(32, 8);  // 32 columns x 8 rows per block
    dim3 grid((M + block.y - 1) / block.y,
              (N + block.x - 1) / block.x);

    matmul_kernel<<<grid, block>>>(
        A_c.data_ptr<float>(),
        B_c.data_ptr<float>(),
        C.data_ptr<float>(),
        M, K, N);

    return C;
}
"""

cpp_src = "torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);"

_mod = load_inline(
    name="tall_skinny_matmul",
    cpp_sources=cpp_src,
    cuda_sources=cuda_src,
    functions=["matmul_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Matrix multiplication C = A * B using a custom CUDA kernel,
    specialized for tall-and-skinny operand shapes (small inner dimension).
    """
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, A, B):
        if not A.is_cuda:
            A = A.cuda()
        if not B.is_cuda:
            B = B.cuda()
        return _mod.matmul_cuda(A, B)

